import{getHeapStatistics,getHeapSpaceStatistics}from'node:v8';
import{PerformanceObserver,performance,constants}from'node:perf_hooks';
export function createNaturalObserver(enabled,config){
 const sampleCapacity=config.heapSampleCapacity,spaceCapacity=config.spaceCapacity,gcCapacity=config.gcEventCapacity,every=config.opaqueStepInterval;
 const fields=['atMs','epochMs','dateNowMs','step','labelIndex','rssBytes','heapTotalBytes','heapUsedBytes','externalBytes','arrayBufferBytes','usedHeapBytes','totalHeapBytes','totalPhysicalHeapBytes','availableHeapBytes','mallocedBytes','externalMemoryBytes','nativeContexts','detachedContexts'];
 const stride=fields.length+spaceCapacity*4,samples=new Float64Array(sampleCapacity*stride),gc=new Float64Array(gcCapacity*6),labels=[],spaceNames=[],labelIds=new Map(),spaceIds=new Map();
 let sampleCount=0,gcCount=0,sampleDrops=0,gcDrops=0,spaceDrops=0,stepCallbacks=0,stepGates=0,clockIssue=false,finished=false;
 const startedMs=performance.now(),timeOrigin=performance.timeOrigin;
 const collect=entries=>{const arrival=performance.now();for(const e of entries){if(gcCount===gcCapacity){gcDrops++;continue;}const i=gcCount++*6;gc[i]=e.startTime;gc[i+1]=e.duration;gc[i+2]=Number(e.detail?.kind??-1);gc[i+3]=Number(e.detail?.flags??-1);gc[i+4]=arrival;gc[i+5]=timeOrigin+e.startTime;}};
 const observer=new PerformanceObserver(list=>collect(list.getEntries()));if(enabled)observer.observe({entryTypes:['gc']});
 function sample(label,step=-1){
  if(!enabled)return;if(sampleCount===sampleCapacity){sampleDrops++;return;}
  let lid=labelIds.get(label);if(lid===undefined){if(labels.length===32){sampleDrops++;return;}lid=labels.length;labels.push(label);labelIds.set(label,lid);}
  const at=performance.now(),date=Date.now(),m=process.memoryUsage(),h=getHeapStatistics(),spaces=getHeapSpaceStatistics();if(Math.abs(date-(timeOrigin+at))>50)clockIssue=true;
  const values=[at,timeOrigin+at,date,step,lid,m.rss,m.heapTotal,m.heapUsed,m.external,m.arrayBuffers,h.used_heap_size,h.total_heap_size,h.total_physical_size,h.total_available_size,h.malloced_memory,h.external_memory,h.number_of_native_contexts,h.number_of_detached_contexts],base=sampleCount++*stride;
  for(let i=0;i<fields.length;i++)samples[base+i]=values[i];
  for(let i=0;i<spaceCapacity*4;i++)samples[base+fields.length+i]=NaN;
  for(const s of spaces){let sid=spaceIds.get(s.space_name);if(sid===undefined){if(spaceNames.length===spaceCapacity){spaceDrops++;continue;}sid=spaceNames.length;spaceNames.push(s.space_name);spaceIds.set(s.space_name,sid);}const i=base+fields.length+sid*4;samples[i]=s.space_used_size;samples[i+1]=s.space_size;samples[i+2]=s.physical_space_size;samples[i+3]=s.space_available_size;}
 }
 return{sample,onStep(step){stepCallbacks++;if(step%every===0){stepGates++;sample('check-step',step);}},async finish(){
  if(finished)throw Error('Observeralreadyfinished');finished=true;for(let i=0;i<config.settleTurnsBothModes;i++)await new Promise(done=>setImmediate(done));if(enabled){collect(observer.takeRecords());observer.disconnect();sample('after-settle');}
  const result={schemaVersion:1,enabled,startedMs,finishedMs:performance.now(),timeOrigin,fields,sampleStride:stride,spaceFields:['usedBytes','sizeBytes','physicalBytes','availableBytes'],spaceNames,labels,sampleCount,sampleCapacity,samples:Array.from(samples.subarray(0,sampleCount*stride)),gcFields:['startMs','durationMs','kind','flags','callbackArrivalMs','epochStartMs'],gcCount,gcCapacity,gcEvents:Array.from(gc.subarray(0,gcCount*6)),stepCallbacks,stepGates,sampleDrops,gcDrops,spaceDrops,clockIssue,gcConstants:Object.fromEntries(Object.entries(constants).filter(([k])=>k.startsWith('NODE_PERFORMANCE_GC_'))),health:sampleDrops===0&&gcDrops===0&&spaceDrops===0&&!clockIssue,scope:'Primitivesonly,fixednumericbuffersallocatedinbothmodes. NoRun/arena/module/ownerreadorretention. Heapoccupiedincludesgarbage;reserved/physical/OSdifferent. GCcallbacksdeferred:usetimestamps,notarrival;nativebacklognotboundedbyourbuffer. NoHeapProfiler/inspector/snapshot/forcedGC.'};return result;
 }};
}

