const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex'),save=(p,x)=>writeFileSync(p,JSON.stringify(x,null,2)+'\n');
async function startPhysical(request){
 const child=spawn(request.sampler,['--pid',String(process.pid),'--interval-ms',String(request.sampling.physicalIntervalMs),'--max-records',String(request.sampling.physicalCapacity)],{stdio:['pipe','pipe','pipe']});
 let chunks=[],errors=[],bytes=0,first='',ready=false,resolveReady,rejectReady;
 const readyPromise=new Promise((ok,no)=>{resolveReady=ok;rejectReady=no;});const timer=setTimeout(()=>{rejectReady(Error('Samplerreadytimeout'));child.stdin.end('STOP\n');},5000);
 const exitPromise=new Promise((ok,no)=>{child.once('error',error=>{clearTimeout(timer);rejectReady(error);no(error);});child.once('close',(code,signal)=>{clearTimeout(timer);if(!ready)rejectReady(Error('Samplerexitbeforeready '+code));ok({code,signal});});});
 child.stdout.on('data',chunk=>{bytes+=chunk.length;if(bytes>2*1024*1024){rejectReady(Error('Sampleroutputoverflow'));child.stdin.end('STOP\n');return;}chunks.push(chunk);if(!ready){first+=chunk.toString('utf8');const n=first.indexOf('\n');if(n!==-1){const r=JSON.parse(first.slice(0,n));if(r.status!=='READY'||r.targetPid!==process.pid)rejectReady(Error('Samplerinvalidready'));else{ready=true;clearTimeout(timer);resolveReady(r);}first='';}}});child.stderr.on('data',chunk=>errors.push(chunk));child.stdin.on('error',()=>{});
 const readyRecord=await readyPromise;return{ready:readyRecord,async stop(){child.stdin.end('STOP\n');const exit=await exitPromise;const lines=Buffer.concat(chunks).toString('utf8').trim().split('\n');const result=JSON.parse(lines.at(-1));if(exit.code!==0||result.status!=='PASS'||result.targetPid!==process.pid)throw Error('Samplerfailure '+JSON.stringify({exit,result,stderr:Buffer.concat(errors).toString('utf8')}));return{...result,ready:readyRecord,exit,stderr:Buffer.concat(errors).toString('utf8'),outputBytes:bytes};}};
}
if(isMainThread){
 const[requestPath,reportPath]=process.argv.slice(2);if(process.argv.length!==4||!requestPath||!reportPath||existsSync(reportPath)||existsSync(reportPath+'.physical.json'))throw Error('ExpectedREQUEST_FRESHREPORT');
 const request=JSON.parse(readFileSync(requestPath,'utf8'));let physical;try{if(request.observer==='on')physical=await startPhysical(request);const worker=new Worker(new URL(import.meta.url),{workerData:{requestPath,reportPath},resourceLimits:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}});await new Promise((ok,no)=>{worker.once('error',no);worker.once('exit',code=>code===0?ok():no(Error('Naturalworkerexit '+code)));});}finally{if(physical){const records=await physical.stop();save(reportPath+'.physical.json',records);}}
 const report=JSON.parse(readFileSync(reportPath,'utf8'));report.physicalTelemetry=request.observer==='on'?{path:reportPath+'.physical.json',sha256:hash(reportPath+'.physical.json')}:{enabled:false};save(reportPath,report);console.log(JSON.stringify({status:report.status,observer:request.observer,report:reportPath,stepCounts:report.stepCounts,heapSamples:report.telemetry.sampleCount,gcEvents:report.telemetry.gcCount,scope:'Diagnosticnotproductionperformanceorlive-rootproof'}));
}else{
 const requestPath=workerData.requestPath,reportPath=workerData.reportPath,request=JSON.parse(readFileSync(requestPath,'utf8'));
 if(request.schemaVersion!==1||!['natural-chronology','natural-smoke'].includes(request.kind)||!['on','off'].includes(request.observer))throw Error('Invalidnaturalrequest');
 const verify=()=>{for(const[p,h]of Object.entries({...request.pins,...request.inputs}))if(realpathSync(p)!==p||hash(p)!==h)throw Error('Pinnedinputdrift '+p);};verify();
 const{runTemplateSteps,runCheckerSteps}=await import(pathToFileURL(request.runtimeHelper).href),observer=createNaturalObserver(request.observer==='on',request.sampling),tag=x=>typeof x?.$==='string'?x.$.split('.').at(-1):null;
 const items=x=>{const a=[];while(tag(x)==='Con'){a.push(x.head);x=x.tail;}if(tag(x)!=='Nil')throw Error('Malformednativelist');return a;},list=a=>a.reduceRight((tail,head)=>({$:'Con',head,tail}),{$:'Nil'}),end=Object.freeze({$:'FeedbackFuelEnd'}),fuelProto={get tail(){return fuel(this.remaining-1);}},fuel=n=>{if(n===0)return end;const x=Object.create(fuelProto);x.$='FeedbackFuelCell';x.remaining=n;return x;};
 const report={schemaVersion:1,status:'RUNNING',diagnosticOnly:true,acceptanceEvidence:false,kind:request.kind,observer:request.observer,image:request.image,imageSha256:hash(request.image),request:requestPath,requestSha256:hash(requestPath),pid:process.pid,threadId,timeOrigin:performance.timeOrigin,runtime:{execPath:process.execPath,versions:process.versions,execArgv:process.execArgv,heapLimitBytes:getHeapStatistics().heap_size_limit},workerPolicy:{stackMiB:256,oldGenerationMiB:6144,youngGenerationMiB:128},exports:request.exports,limits:request.limits,checksExcluded:0,outputPatches:0,phases:[],stepCounts:{},scope:'Actualownparse/expand/check;noASTtransport/imagepatch/algorithmchange. On/offfixeddriverandfixedsourceURL;timingsdiagnostic,notcleanproductiongain. Bothkeepordinaryvalue-lifetimes/noexplicitresultrelease.'};save(reportPath,report);
 const phase=async(name,action)=>{observer.sample(name+'-start');report.activePhase=name;save(reportPath,report);const startMs=performance.now(),before=process.cpuUsage(),result=await action(),cpu=process.cpuUsage(before),endMs=performance.now();report.phases.push({phase:name,startMs,endMs,epochStartMs:performance.timeOrigin+startMs,epochEndMs:performance.timeOrigin+endMs,elapsedMs:endMs-startMs,userCpuMs:cpu.user/1000,systemCpuMs:cpu.system/1000,memoryEnd:process.memoryUsage()});delete report.activePhase;observer.sample(name+'-end');save(reportPath,report);return result;};
 try{
  if(request.kind==='natural-smoke'){
   report.scope='Controlledallocationandopaque-callbacksafetysmoke;NOcompilerimageimport,parser,checker,performanceorlive-rootqualification.';report.compilerImageImported=false;
   const before=process.memoryUsage(),poison=new Proxy({},{get(){throw Error('ObserverreadopaqueRun');}});observer.sample('smoke-before');
   const buffer=new Uint8Array(64*1024*1024);buffer.fill(90);const after=process.memoryUsage();observer.sample('smoke-array-buffer-held');
   const ring=new Array(4096);for(let i=0;i<1000000;i++)ring[i&4095]={index:i,value:i+1};for(let i=0;i<40000;i++)observer.onStep(i,poison);
   await new Promise(done=>setTimeout(done,600));observer.sample('smoke-held-after-delay');report.telemetry=await observer.finish();
   const checksum=buffer[0]+buffer[buffer.length>>>1]+buffer[buffer.length-1],delta=after.arrayBuffers-before.arrayBuffers;
   if(checksum!==270||delta<64*1024*1024||report.telemetry.stepCallbacks!==40000||report.telemetry.stepGates!==3||!report.telemetry.health)throw Error('Controlledobserverbehaviorfailed');
   report.smoke={checksum,arrayBufferDeltaBytes:delta,opaqueRunReadTrapNotTriggered:true,holdMs:600,globalGCExposed:typeof globalThis.gc==='function'};
   report.status='PASS_CONTROLLED_NATIVE_OBSERVER_SMOKE';verify();save(reportPath,report);
  }else{
  const api=await phase('startup',async()=>{const value=(await import(pathToFileURL(request.image).href)).default;if(!request.exports.every(k=>typeof value?.[k]==='function'))throw Error('IncompleteABI');return value;});
  let modules=[],declarations=0;const seen=new Map();
  await phase('load-parse',()=>{const active=new Set(),observed=new Set(),observe=p=>{const path=realpathSync(p);if(!Object.hasOwn(request.inputs,path))throw Error('Unexpectedinput '+path);observed.add(path);return path;},namespace=(scope,path)=>path==='Base'?'':posix.normalize(isAbsolute(path)?path.replace(/\.bend$/,''):posix.dirname(scope)+'/'+path.replace(/\.bend$/,''));
   const visit=(file,scope)=>{const p=observe(file);if(active.has(p))throw Error('Importcycle');if(seen.has(p)){if(seen.get(p)!==scope)throw Error('Namespaceconflict');return;}seen.set(p,scope);active.add(p);const feedback=api.parse_with_fuel(fuel(8000000),p,readFileSync(p,'utf8'));if(tag(feedback)!=='FeedbackComplete'||tag(feedback.value.result)!=='ParseSuccess')throw Error('Ownparsefailure '+p);const module=feedback.value.result.module;declarations+=items(module.declarations).length;for(const top of items(module.declarations))if(tag(top)==='DefTop'&&tag(top.definition.body)==='DefImports')for(const path of items(top.definition.body.paths))if(path.endsWith('.js'))observe(resolve(dirname(p),path));for(const imported of items(module.imports)){const path=imported.path;if(path.endsWith('.js'))observe(resolve(dirname(p),path));else if(!path.endsWith('.c'))visit(path==='Base'?resolve(request.repository,'bend2/base.bend'):resolve(dirname(p),path),namespace(scope,path));}modules.push(api.parsed_module(scope,module));active.delete(p);};
   visit(request.root,'');if(observed.size!==Object.keys(request.inputs).length)throw Error('Ownparseromittedinput');report.moduleCount=seen.size;report.sourceDeclarations=declarations;modules=list(modules);
  });
  let expanded=await phase('expand',()=>runTemplateSteps({...api,expand_modules_start:input=>{modules=undefined;return api.expand_modules_start(input);}},modules,{onFinish(_,steps){report.stepCounts.expand=steps;}}));if(tag(expanded)!=='ExpandSuccess')throw Error('Ownexpandfailure');
  let checked=await phase('check',()=>runCheckerSteps({...api,check_expanded_start:input=>{expanded=undefined;return api.check_expanded_start(input);}},expanded.modules,{onStep:observer.onStep,onFinish(_,steps){report.stepCounts.check=steps;}}));if(tag(checked)!=='CheckSuccess')throw Error('Owncheckfailure');
  if(report.moduleCount!==request.expected.modules||report.sourceDeclarations!==request.expected.declarations||report.stepCounts.expand!==request.expected.expand||report.stepCounts.check!==request.expected.check)throw Error('Frozenworkcountdiffers');
  observer.sample('verification-start');verify();observer.sample('verification-end');report.telemetry=await observer.finish();report.fullCheckSuccess=true;report.phaseCpuScope='NodeprocessCPUincludesworker/helperthreads,excludesexternalphysicalsamplerchild';report.status='PASS_FULL_FROZEN_NATURAL_CHRONOLOGY';save(reportPath,report);
  }
 }catch(error){report.status='FAIL';report.error=String(error);report.stack=error?.stack;try{report.telemetry=await observer.finish();}catch{}save(reportPath,report);throw error;}
}
